function distanceKm(a: { lat: number; lon: number }, b: { lat: number; lon: number }): number {
  const dLat = toRad(b.lat - a.lat);
  const dLon = toRad(b.lon - a.lon);
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(s), Math.sqrt(1 - s));
}

export function checkZipRadius(zip: string, radiusKm = 30): {
  ok: boolean;
  city: string;
  distanceKm: number;
  reason: string;
} {
  const clean = String(zip || "").trim();
  if (!/^\d{5}$/.test(clean)) {
    return { ok: false, city: "", distanceKm: 0, reason: "Bitte eine gueltige PLZ eingeben." };
  }

  const geo = ZIP_GEO[clean];
  if (!geo) {
    return { ok: false, city: "", distanceKm: 0, reason: "PLZ außerhalb des definierten Einsatzgebiets." };
  }

  const km = distanceKm(CENTER, geo);
  return {
    ok: km <= radiusKm,
    city: geo.city,
    distanceKm: Number(km.toFixed(1)),
    reason: km <= radiusKm ? "" : `Entfernung ${km.toFixed(1)} km liegt über dem Radius von ${radiusKm} km.`,
  };
}

export function getSupportedZipCount(): number {
  return Object.keys(ZIP_GEO).length;
}
